settings.custom_css:
selector .elementor-accordion-item{border:0;border-bottom:1px solid #e6dfcd}
selector .elementor-accordion-item:first-child{border-top:1px solid #e6dfcd}
selector .elementor-tab-title{transition:color .2s ease}
selector .elementor-tab-content{border-top:0}
selector .elementor-tab-content p:last-child{margin-bottom:0}

page_settings.custom_css:
/* Omnicare — estilos globais da página */
html{scroll-behavior:smooth;scroll-padding-top:96px}
.omni-title .elementor-heading-title em{font-style:italic;font-weight:500;color:#428265}
.omni-on-dark .omni-title .elementor-heading-title em{color:#fae6cb}
.omni-eyebrow .elementor-heading-title{display:inline-flex;align-items:center;gap:12px}
.omni-eyebrow .elementor-heading-title::before{content:"";width:28px;height:1px;background:currentColor;opacity:.55}
.omni-on-dark .elementor-widget-text-editor p:last-child{margin-bottom:0}
.omni-btn .elementor-button{transition:background-color .2s ease,color .2s ease,border-color .2s ease,transform .16s ease-out}
.omni-btn .elementor-button:active{transform:scale(.97)}
.omni-link .elementor-button{border-radius:0!important;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:6px}
.omni-card{transition:border-color .3s ease,box-shadow .3s ease,transform .3s cubic-bezier(.23,1,.32,1)}
@media (hover:hover) and (pointer:fine){
  .omni-card:hover{border-color:#cdd8ce;transform:translateY(-3px);box-shadow:0 22px 44px -28px rgba(31,42,35,.28)}
}
@media (min-width:1025px){.omni-sticky{position:sticky;top:120px}}
a:focus-visible,.elementor-button:focus-visible,.elementor-tab-title:focus-visible{outline:2px solid #428265;outline-offset:4px}
/* Animações de entrada: suaves e curtas */
.elementor-element.animated.fadeInUp{animation-name:omniRise;animation-duration:.8s;animation-timing-function:cubic-bezier(.23,1,.32,1)}
.elementor-element.animated.fadeIn{animation-duration:1s;animation-timing-function:cubic-bezier(.23,1,.32,1)}
@keyframes omniRise{from{opacity:0;transform:translate3d(0,18px,0)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .elementor-element.animated{animation:none!important}
  .omni-card,.omni-card:hover,.omni-btn .elementor-button:active{transform:none!important}
}
